#include <pybind11/complex.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/rad_astro/filewriter.h>
// pydoc.h is automatically generated in the build directory
#include <filewriter_pydoc.h>

void bind_filewriter(py::module& m)
{

    using filewriter    = ::gr::rad_astro::filewriter;


    py::class_<filewriter, gr::block, gr::basic_block,
        std::shared_ptr<filewriter>>(m, "filewriter", D(filewriter))

        .def(py::init(&filewriter::make),
           py::arg("vlen"),
           py::arg("filename"),
           D(filewriter,make)
        )
        



        ;




}








